H.background();
const w = H.W, h = H.H;
const a = P.a, b = P.b, c = P.c, r = P.r;
const coeffs = [a, b, c];
const x0 = 150, dx = 170, rowY = 150, gap = 64;
H.text("Synthetic division: divide ax² + bx + c by (x − r)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("r = " + r.toFixed(1) + "    coeffs  [" + a.toFixed(1) + ", " + b.toFixed(1) + ", " + c.toFixed(1) + "]", 24, 52, { color: H.colors.sub, size: 13 });
H.rect(70, rowY - 28, 36, gap * 2 + 24, { stroke: H.colors.accent2, width: 2, radius: 4 });
H.text(r.toFixed(1), 76, rowY + gap, { color: H.colors.accent2, size: 15, weight: 700 });
const step = Math.floor((t % 6) / 2);
const out = [];
for (let i = 0; i < coeffs.length; i++) {
  const cx = x0 + i * dx;
  const mul = i === 0 ? 0 : out[i - 1] * r;
  out.push(coeffs[i] + mul);
  const active = i <= step;
  H.text(coeffs[i].toFixed(1), cx, rowY, { color: H.colors.ink, size: 16, weight: 600 });
  if (i > 0) {
    H.text((mul >= 0 ? "+" : "") + mul.toFixed(1), cx, rowY + gap, { color: active ? H.colors.accent : H.colors.grid, size: 15 });
    H.arrow(cx - dx + 16, rowY + 16, cx - 10, rowY + gap - 10, { color: active ? H.colors.violet : H.colors.grid, width: 2 });
  }
  H.text(out[i].toFixed(1), cx, rowY + 2 * gap, { color: active ? H.colors.good : H.colors.grid, size: 18, weight: 700 });
}
H.line(x0 - 34, rowY + gap + 22, x0 + (coeffs.length - 1) * dx + 36, rowY + gap + 22, { color: H.colors.axis, width: 1.5 });
H.text("quotient:  " + out[0].toFixed(1) + " x + " + out[1].toFixed(1) + "      remainder:  " + out[2].toFixed(1), 24, h - 38, { color: H.colors.good, size: 15, weight: 600 });
const pulse = x0 + step * dx;
H.circle(pulse, rowY + 2 * gap - 6, 18 + 4 * Math.sin(t * 4), { stroke: H.colors.warn, width: 2 });
